  status=text("连接云盘…",13,a.muted);status.setLineSpacing(dp(3),1.08f);status.setPadding(dp(4),dp(5),dp(4),dp(10));addView(status);progress=new ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(true);addView(progress,new LinearLayout.LayoutParams(-1,dp(3)));
