 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 TextView text(String value,int size,int color){TextView view=new TextView(a);view.setText(value);view.setTextSize(size);view.setTextColor(color);view.setIncludeFontPadding(false);return view;}
