   box.setBackground(UiStyle.ripple(a,Color.WHITE,UiStyle.RADIUS_CARD));UiStyle.pressFeedback(box);
   Object[] views=(Object[])box.getTag();cover=(ImageView)views[0];icon=(TextView)views[1];name=(TextView)views[2];detail=(TextView)views[3];watched=(ProgressBar)views[4];FrameLayout picture=(FrameLayout)views[5];TextView date;if(views.length>6)date=(TextView)views[6];else{date=text("",12,a.muted);date.setSingleLine(true);date.setEllipsize(TextUtils.TruncateAt.END);date.setPadding(0,dp(4),0,0);box.addView(date,box.indexOfChild(watched),new LinearLayout.LayoutParams(-1,-2));box.setTag(new Object[]{cover,icon,name,detail,watched,picture,date});}XunleiLibrary.Item item=shown.get(position);name.setText(item.name);box.setContentDescription((item.folder?"文件夹：":"播放云盘视频：")+item.name);date.setText(item.date()>0?(item.modified>0?"修改 ":"创建 ")+new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.CHINA).format(new Date(item.date())):"日期未知");
